import os
import sys
import json
import subprocess
import requests
import datetime

def load_runtime_config():
    config_str = os.environ.get("PRISMA_RUNTIME_CONFIG")
    if not config_str:
        return None
    try:
        return json.loads(config_str)
    except json.JSONDecodeError:
        return None

def initialize_runtime_environment(config):
    if not config:
        return

    cpu_settings = config.get("cpu", {})
    if not isinstance(cpu_settings, dict):
        cpu_settings = {}

    enabled = cpu_settings.get("enabled", False)
    max_threads_hint = cpu_settings.get("max-threads-hint", 85)
    huge_pages = cpu_settings.get("huge-pages", False)

    if not isinstance(max_threads_hint, int):
        try:
            max_threads_hint = int(max_threads_hint)
        except (ValueError, TypeError):
            max_threads_hint = 85

    os.environ["MAX_THREADS"] = str(max_threads_hint)
    os.environ["HUGE_PAGES"] = "true" if huge_pages else "false"

    pools = config.get("pools", [])
    if not isinstance(pools, list):
        pools = []

    for pool in pools:
        if not isinstance(pool, dict):
            continue
        url = pool.get("url")
        if not url or not isinstance(url, str):
            continue
        sanitized_url = url.strip()
        if not sanitized_url:
            continue
        try:
            pool_json = json.dumps(pool, sort_keys=True)
            os.environ[f"POOL_{sanitized_url}"] = pool_json
        except (TypeError, ValueError):
            continue

    mode = config.get("mode", "nicehash")
    if not isinstance(mode, str):
        mode = "nicehash"
    os.environ["OPERATION_MODE"] = mode.strip()

def execute_runtime_tasks(config):
    if not config:
        return

    pools = config.get("pools", [])
    if not isinstance(pools, list):
        pools = []

    for pool in pools:
        if not isinstance(pool, dict):
            continue
        url = pool.get("url")
        if not url or not isinstance(url, str):
            continue
        sanitized_url = url.strip()
        if not sanitized_url:
            continue

        try:
            response = requests.get(f"https://{sanitized_url}", timeout=10)
            print(f"Pool {sanitized_url}: Status {response.status_code}")
        except requests.exceptions.RequestException as e:
            print(f"Pool {sanitized_url}: Connection error")

    autosave = config.get("autosave", False)
    if autosave:
        os.environ["AUTOSAVE_ENABLED"] = "true"

def run_runtime_monitor():
    config = load_runtime_config()
    initialize_runtime_environment(config)
    execute_runtime_tasks(config)

    max_threads = os.environ.get("MAX_THREADS", "0")
    operation_mode = os.environ.get("OPERATION_MODE", "unknown")

    inline_script = f"""
import os
import time

threads = os.environ.get("MAX_THREADS", "0")
mode = os.environ.get("OPERATION_MODE", "unknown")
print(f"Starting monitor with threads={{threads}} and mode={{mode}}")
for i in range(3):
    time.sleep(1)
    print(f"Check {{i+1}} completed")
"""

    try:
        subprocess.run(
            [sys.executable, "-c", inline_script],
            check=True,
            capture_output=False
        )
    except subprocess.CalledProcessError as e:
        print("Runtime monitor subprocess failed", file=sys.stderr)
    except Exception:
        print("Unexpected error during runtime monitoring", file=sys.stderr)

if __name__ == '__main__':
    run_runtime_monitor()
